<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Throwable; use Illuminate\View\View; use Illuminate\Http\Request; use Illuminate\Http\Response; use Illuminate\Support\Facades\Mail; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Services\Dezerx\Emails; use Pterodactyl\Http\Controllers\Controller; use Illuminate\Notifications\Messages\MailMessage; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class EmailsController extends Controller { public function __construct(private readonly AlertsMessageBag $alert) { } public function index(Request $request): View { $templates = Emails::all(); $selected = (string) $request->query('template', ''); if (!Emails::knows($selected)) { $selected = (string) array_key_first($templates); } return view('admin.dezerx.emails.index', [ 'templates' => $templates, 'selected' => $selected, 'template' => $templates[$selected], 'defaults' => Emails::DEFAULTS[$selected], 'pane' => $request->query('pane') === 'layout' ? 'layout' : 'message', 'layout' => Emails::layout(), 'layoutDefault' => Emails::layoutDefault(), 'layoutIsCustom' => Emails::layoutIsCustom(), 'layoutVariables' => Emails::LAYOUT_VARIABLES, 'bodyVariables' => Emails::BODY_VARIABLES, 'seed' => Emails::seed($selected), ]); } public function update(Request $request, string $key): RedirectResponse { $this->known($key); $data = $request->validate([ 'subject' => ['required', 'string', 'max:200'], 'greeting' => ['nullable', 'string', 'max:120'], 'body' => ['required', 'string', 'max:2000'], 'action' => ['nullable', 'string', 'max:60'], 'outro' => ['nullable', 'string', 'max:400'], 'mode' => ['nullable', 'string', 'in:simple,html'], 'html' => ['nullable', 'string', 'max:' . Emails::HTML_LIMIT], ]); Emails::save($key, [ 'subject' => $data['subject'], 'greeting' => $data['greeting'] ?? '', 'body' => $data['body'], 'action' => $data['action'] ?? '', 'outro' => $data['outro'] ?? '', ]); Emails::saveHtml($key, ($data['mode'] ?? 'simple') === 'html' ? (string) ($data['html'] ?? '') : ''); $this->alert->success('That message has been saved.')->flash(); return $this->back($key); } public function reset(string $key): RedirectResponse { $this->known($key); Emails::reset($key); $this->alert->success('That message is back to the wording this theme ships with.')->flash(); return $this->back($key); } public function saveLayout(Request $request): RedirectResponse { $data = $request->validate([ 'layout' => ['required', 'string', 'max:' . Emails::LAYOUT_LIMIT], ]); if (!str_contains($data['layout'], '{{ content }}') && !preg_match('/\{\{\s*content\s*\}\}/i', $data['layout'])) { $this->alert->danger('That layout has no {{ content }} in it, so every message would arrive empty. Nothing was saved.')->flash(); return $this->back(null, 'layout'); } Emails::saveLayout($data['layout']); $this->alert->success('The layout has been saved. Every message uses it.')->flash(); return $this->back(null, 'layout'); } public function resetLayout(): RedirectResponse { Emails::resetLayout(); $this->alert->success('The layout is back to the one this theme ships with.')->flash(); return $this->back(null, 'layout'); } public function preview(Request $request, string $key): Response { $this->known($key); return $this->page($this->html($request, $key)); } public function draft(Request $request): Response { $key = (string) $request->input('template', ''); $this->known($key); $parts = Emails::renderInput([ 'subject' => (string) $request->input('subject', ''), 'greeting' => (string) $request->input('greeting', ''), 'body' => (string) $request->input('body', ''), 'action' => (string) $request->input('action', ''), 'outro' => (string) $request->input('outro', ''), ], $this->values($request), url('/')); $html = $request->input('mode') === 'html' ? (string) $request->input('html', '') : null; return $this->page(Emails::document([ 'key' => $key, 'values' => $this->values($request) + ['panel' => (string) config('app.name', 'Pterodactyl')], 'subject' => $parts['subject'], 'greeting' => $parts['greeting'], 'introLines' => $parts['lines'], 'actionText' => $parts['action']['label'] ?? '', 'actionUrl' => $parts['action']['url'] ?? '', 'outroLines' => $parts['outro'], 'layout' => (string) $request->input('layout', ''), ] + ($html === null ? [] : ['html' => $html]))); } public function test(Request $request, string $key): RedirectResponse { $this->known($key); $address = (string) $request->user()->email; try { $message = $this->message($request, $key); Mail::html($this->html($request, $key), function ($mail) use ($address, $message) { $mail->to($address)->subject((string) $message->subject); }); $this->alert->success('A copy has been sent to ' . $address . '.')->flash(); } catch (Throwable $exception) { $this->alert->danger('That could not be sent: ' . $exception->getMessage())->flash(); } return $this->back($key); } private function back(?string $key = null, string $pane = 'message'): RedirectResponse { return redirect()->route('admin.dezerx.emails', array_filter([ 'template' => $key, 'pane' => $pane === 'layout' ? 'layout' : null, ])); } private function page(string $html): Response { return new Response($html, 200, [ 'Content-Type' => 'text/html; charset=utf-8', 'Content-Security-Policy' => "default-src 'none'; img-src * data:; style-src 'unsafe-inline'; font-src *", 'X-Frame-Options' => 'SAMEORIGIN', ]); } private function known(string $key): void { if (!Emails::knows($key)) { throw new NotFoundHttpException(); } } private function values(Request $request): array { $user = $request->user(); return [ 'name' => (string) $user->name, 'username' => (string) $user->username, 'email' => (string) $user->email, 'server' => 'Example server', ]; } private function message(Request $request, string $key): MailMessage { return Emails::apply(new MailMessage(), $key, $this->values($request), url('/')); } private function html(Request $request, string $key): string { return view('notifications::email', $this->message($request, $key)->data())->render(); } } 